B=[
('الْجَزِيرَةُ','Ada',[
('يُحْكَى أَنَّ فِي إِحْدَى جُزُرِ الْهِنْدِ الَّتِي تَحْتَ خَطِّ الِاسْتِوَاءِ جَزِيرَةً مُعْتَدِلَةَ الْهَوَاءِ.','Anlatılır ki ekvator çizgisinin altındaki Hint adalarından birinde havası mutedil bir ada vardı.'),
('وَكَانَتْ أَرْضُهَا خِصْبَةً، وَأَشْجَارُهَا كَثِيرَةً، وَلَيْسَ فِيهَا إِنْسَانٌ وَاحِدٌ.','Toprağı verimli, ağaçları çoktu ve içinde tek bir insan yoktu.'),
('وَكَانَ بِالْقُرْبِ مِنْهَا جَزِيرَةٌ عَظِيمَةٌ عَامِرَةٌ، يَمْلِكُهَا مَلِكٌ شَدِيدُ الْأَنَفَةِ وَالْغَيْرَةِ.','Ona yakın, büyük ve meskûn bir ada vardı; onu gururu ve kıskançlığı şiddetli bir kral yönetiyordu.'),
('وَكَانَتْ لَهُ أُخْتٌ ذَاتُ جَمَالٍ، فَمَنَعَهَا مِنَ الزَّوَاجِ، إِذْ لَمْ يَجِدْ لَهَا كُفْئًا.','Onun güzel bir kız kardeşi vardı; ona denk birini bulamadığı için onu evlenmekten men etti.'),
('وَكَانَ لَهُ قَرِيبٌ يُسَمَّى يَقْظَانَ، فَتَزَوَّجَهَا سِرًّا عَلَى وَجْهٍ جَائِزٍ فِي مَذْهَبِهِمْ.','Yakzân adında bir akrabası vardı; onunla kendi mezheplerinde caiz olan bir şekilde gizlice evlendi.'),
('ثُمَّ حَمَلَتْ مِنْهُ، وَوَضَعَتْ طِفْلًا جَمِيلًا.','Sonra ondan hamile kaldı ve güzel bir çocuk doğurdu.'),
('فَخَافَتْ أَنْ يَفْتَضِحَ أَمْرُهَا، وَأَنْ يَقْتُلَهُ أَخُوهَا.','Durumunun ortaya çıkmasından ve kardeşinin onu öldürmesinden korktu.')]),
('التَّابُوتُ عَلَى الْمَاءِ','Su üstündeki sandık',[
('فَوَضَعَتْهُ فِي تَابُوتٍ أَحْكَمَتْ زَمَّهُ، بَعْدَ أَنْ أَرْوَتْهُ مِنَ الرَّضَاعِ.','Onu iyice emzirdikten sonra ağzını sağlamca kapattığı bir sandığa koydu.'),
('وَخَرَجَتْ بِهِ فِي أَوَّلِ اللَّيْلِ، فِي جُمْلَةٍ مِنْ خَدَمِهَا وَثِقَاتِهَا، إِلَى سَاحِلِ الْبَحْرِ.','Gecenin başında, hizmetçilerinden ve güvendiklerinden bir toplulukla onu deniz kıyısına götürdü.'),
('وَقَلْبُهَا يَحْتَرِقُ صَبَابَةً بِهِ وَخَوْفًا عَلَيْهِ.','Kalbi ona olan sevgiden ve onun için duyduğu korkudan yanıyordu.'),
('ثُمَّ وَدَّعَتْهُ وَقَالَتِ: «اللَّهُمَّ إِنَّكَ خَلَقْتَ هَذَا الطِّفْلَ وَلَمْ يَكُنْ شَيْئًا مَذْكُورًا.»','Sonra onunla vedalaştı ve dedi ki: “Allah’ım, bu çocuğu o anılmaya değer bir şey değilken Sen yarattın.”'),
('«وَإِنِّي قَدْ أَسْلَمْتُهُ إِلَى لُطْفِكَ، وَرَجَوْتُ لَهُ فَضْلَكَ، فَكُنْ لَهُ، وَلَا تُسْلِمْهُ.»','“Onu Senin lütfuna teslim ettim ve onun için lütfunu umdum; ona sahip çık ve onu bırakma.”'),
('ثُمَّ قَذَفَتْ بِهِ فِي الْيَمِّ.','Sonra onu denize bıraktı.'),
('فَصَادَفَ ذَلِكَ جَرْيَ الْمَاءِ بِقُوَّةِ الْمَدِّ، فَاحْتَمَلَهُ إِلَى سَاحِلِ الْجَزِيرَةِ الْأُخْرَى.','Bu, suyun med gücüyle akışına denk geldi ve su onu öbür adanın kıyısına taşıdı.')]),
('الظَّبْيَةُ','Ceylan',[
('وَكَانَ الْمَدُّ قَدْ أَدْخَلَ التَّابُوتَ إِلَى أَجَمَةٍ مُلْتَفَّةِ الشَّجَرِ، كَنِينَةٍ مِنَ الرِّيحِ وَالْمَطَرِ.','Med sandığı rüzgârdan ve yağmurdan korunaklı, ağaçları sık bir çalılığa sokmuştu.'),
('ثُمَّ أَخَذَ الْمَاءُ فِي الْجَزْرِ، وَبَقِيَ التَّابُوتُ فِي ذَلِكَ الْمَوْضِعِ.','Sonra su çekilmeye başladı ve sandık o yerde kaldı.'),
('فَلَمَّا اشْتَدَّ الْجُوعُ بِالطِّفْلِ بَكَى وَاسْتَغَاثَ وَعَالَجَ الْحَرَكَةَ.','Çocuğun açlığı şiddetlenince ağladı, yardım istedi ve kıpırdamaya çalıştı.'),
('فَوَقَعَ صَوْتُهُ فِي أُذُنِ ظَبْيَةٍ فَقَدَتْ طَلَاهَا.','Sesi yavrusunu kaybetmiş bir ceylanın kulağına ulaştı.'),
('فَتَتَبَّعَتِ الصَّوْتَ وَهِيَ تَتَخَيَّلُ أَنَّهُ طَلَاهَا، حَتَّى وَصَلَتْ إِلَى التَّابُوتِ.','Onun kendi yavrusu olduğunu hayal ederek sesi izledi ve sandığa ulaştı.'),
('فَفَحَصَتْ عَنْهُ بِأَظْلَافِهَا، حَتَّى طَارَ لَوْحٌ مِنْ أَعْلَاهُ.','Toynaklarıyla onu eşeledi; sonunda üstünden bir tahta fırladı.'),
('فَحَنَّتْ عَلَيْهِ وَرَئِمَتْ بِهِ، وَأَلْقَمَتْهُ حَلَمَتَهَا، وَأَرْوَتْهُ لَبَنًا سَائِغًا.','Ona şefkat gösterdi, onu bağrına bastı, memesini ağzına verdi ve onu lezzetli bir sütle doyurdu.')]),
('الطُّفُولَةُ','Çocukluk',[
('وَمَا زَالَتْ تَتَعَهَّدُهُ وَتُرَبِّيهِ، وَتَدْفَعُ عَنْهُ الْأَذَى.','Ona bakmaya, onu büyütmeye ve ondan eziyeti uzaklaştırmaya devam etti.'),
('وَسُمِّيَ الطِّفْلُ فِي رِوَايَةِ الْحِكَايَةِ: حَيَّ بْنَ يَقْظَانَ.','Çocuğa hikâyenin anlatımında Hayy b. Yakzân adı verildi.'),
('وَكَانَتِ الظَّبْيَةُ تَرْعَى فِي الْمَرَاعِي الطَّيِّبَةِ، فَكَثُرَ لَحْمُهَا وَدَرَّ لَبَنُهَا.','Ceylan güzel otlaklarda otluyordu; eti çoğaldı ve sütü bollaştı.'),
('فَإِذَا عَطِشَ الطِّفْلُ أَرْوَتْهُ، وَإِذَا ضَحِيَ ظَلَّلَتْهُ، وَإِذَا خَصِرَ أَدْفَأَتْهُ.','Çocuk susayınca onu suya kandırır, güneşte kalınca onu gölgeler, üşüyünce onu ısıtırdı.'),
('وَكَانَ يَمْشِي مَعَ الظِّبَاءِ، وَيُحَاكِي أَصْوَاتَهَا حَتَّى لَا يَكَادُ يُفَرِّقُ بَيْنَهَا.','Ceylanlarla birlikte yürür ve onların seslerini neredeyse ayırt edilemeyecek kadar taklit ederdi.'),
('وَكَذَلِكَ حَاكَى أَصْوَاتَ الطُّيُورِ وَأَنْوَاعَ سَائِرِ الْحَيَوَانِ.','Aynı şekilde kuşların ve diğer hayvan türlerinin seslerini de taklit etti.'),
('وَأَلِفَ الْوَحْشَ وَأَلِفَتْهُ، فَلَمْ تَنْكِرْهُ وَلَمْ يُنْكِرْهَا.','Vahşi hayvanlara alıştı, onlar da ona alıştı; onlar onu yadırgamadı, o da onları yadırgamadı.')]),
('الْعُرْيُ وَالْحِيلَةُ','Çıplaklık ve çare',[
('ثُمَّ نَظَرَ إِلَى جَمِيعِ الْحَيَوَانَاتِ، فَرَأَى كُلَّ وَاحِدٍ مِنْهَا كَاسِيًا بِالْأَوْبَارِ وَالْأَشْعَارِ وَالرِّيشِ.','Sonra bütün hayvanlara baktı; her birinin yünle, kılla ve tüyle örtülü olduğunu gördü.'),
('وَرَأَى لَهَا سُرْعَةَ الْعَدْوِ، وَقُوَّةَ الْبَطْشِ، وَالْأَسْلِحَةَ الْمُعَدَّةَ مِنَ الْقُرُونِ وَالْأَنْيَابِ وَالْمَخَالِبِ.','Onların koşu hızını, saldırı gücünü, boynuzlardan, azı dişlerinden ve pençelerden hazırlanmış silahlarını gördü.'),
('ثُمَّ رَجَعَ إِلَى نَفْسِهِ، فَرَأَى مَا بِهِ مِنَ الْعُرْيِ وَعَدَمِ السِّلَاحِ وَضَعْفِ الْعَدْوِ.','Sonra kendine döndü ve kendisindeki çıplaklığı, silahsızlığı ve koşu zayıflığını gördü.'),
('فَكَانَ ذَلِكَ يُكْرِبُهُ وَيَسُوءُهُ.','Bu onu kederlendiriyor ve üzüyordu.'),
('فَاتَّخَذَ مِنْ أَوْرَاقِ الشَّجَرِ الْعَرِيضَةِ شَيْئًا جَعَلَ بَعْضَهُ خَلْفَهُ وَبَعْضَهُ قُدَّامَهُ.','Ağaçların geniş yapraklarından bir şey edindi; bir kısmını arkasına, bir kısmını önüne koydu.'),
('وَاتَّخَذَ مِنْ أَغْصَانِ الشَّجَرِ عِصِيًّا سَوَّى أَطْرَافَهَا، وَكَانَ يُهَوِّلُ بِهَا عَلَى الْوُحُوشِ.','Ağaç dallarından uçlarını düzelttiği sopalar edindi ve onlarla vahşi hayvanları korkuturdu.'),
('فَعَلِمَ أَنَّ لِيَدِهِ فَضْلًا كَثِيرًا عَلَى يَدِ غَيْرِهِ؛ فَبِهَا يَصْنَعُ مَا لَا يَصْنَعُ الْحَيَوَانُ بِأَعْضَائِهِ.','Elinin başkalarının elinden çok üstün olduğunu anladı; onunla hayvanın uzuvlarıyla yapamadığını yapıyordu.')]),
('مَوْتُ الظَّبْيَةِ','Ceylanın ölümü',[
('وَلَمَّا كَبِرَتِ الظَّبْيَةُ وَضَعُفَتْ، صَارَ يَرْتَادُ بِهَا الْمَرَاعِيَ الْخِصْبَةَ، وَيَجْتَنِي لَهَا الثِّمَارَ.','Ceylan yaşlanıp zayıflayınca Hayy onu verimli otlaklara götürür, ona meyveler toplardı.'),
('وَمَا زَالَ الضَّعْفُ يَزِيدُ بِهَا حَتَّى أَدْرَكَهَا الْمَوْتُ.','Zayıflığı artmaya devam etti; sonunda ölüm ona erişti.'),
('فَسَكَنَتْ حَرَكَاتُهَا، وَتَعَطَّلَتْ أَفْعَالُهَا.','Hareketleri durdu, fiilleri kesildi.'),
('فَلَمَّا رَآهَا عَلَى تِلْكَ الْحَالِ جَزِعَ جَزَعًا شَدِيدًا، وَكَادَتْ نَفْسُهُ تَفِيضُ أَسَفًا عَلَيْهَا.','Onu o hâlde görünce şiddetle feryat etti; nerdeyse canı ona duyduğu acıdan çıkacaktı.'),
('وَكَانَ يُنَادِيهَا بِالصَّوْتِ الَّذِي كَانَتْ عَادَتُهَا أَنْ تُجِيبَهُ عِنْدَ سَمَاعِهِ.','Onu, işittiğinde hep cevap verdiği sesle çağırıyordu.'),
('فَلَا يَرَى لَهَا عِنْدَ ذَلِكَ حَرَكَةً وَلَا تَغَيُّرًا.','Ama o zaman onda ne bir hareket ne bir değişiklik görüyordu.'),
('فَكَانَ يَنْظُرُ إِلَى أُذُنَيْهَا وَإِلَى عَيْنَيْهَا، فَلَا يَرَى بِهَا آفَةً ظَاهِرَةً.','Kulaklarına ve gözlerine bakıyor, onlarda görünür bir kusur göremiyordu.')]),
]
